-- Migration 049: pictures (public/lec/ch2-*.svg) on the 10 сынып informatics chapter 2 slides of 046. Idempotent: sets slide.img/alt by lesson number and slide title.
-- GENERATED by scripts/gen-ch2-img.mjs. Deploy the SVGs (push to main) BEFORE applying this.

do $ch2img$
declare r record; n int := 0; m uuid;
begin
  select cm.id into m from public.cf_curr_modules cm join public.cf_curr_courses cc on cc.id = cm.course_id
   where cc.subject = 'Информатика' and cc.grade = 10 and cm.title like '2-тарау.%';
  if m is null then raise exception 'chapter 2 module not found'; end if;
  for r in select * from (values
    ($sl$2.1$sl$, $sl$Екілік жүйе (binary)$sl$, $sl$lec/ch2-binary.svg$sl$, $sl$Екілік разрядтар 128, 64, 32, 16, 8, 4, 2, 1; 10101000 = 128 + 32 + 8 = 168$sl$, true),
    ($sl$2.1$sl$, $sl$Сегіздік және он алтылық жүйе$sl$, $sl$lec/ch2-bases.svg$sl$, $sl$167 саны ондық, екілік, сегіздік және он алтылық жүйеде$sl$, true),
    ($sl$2.2$sl$, $sl$Қосудың төрт ережесі$sl$, $sl$lec/ch2-carry.svg$sl$, $sl$Екілік қосудың төрт жағдайы және 1 + 1 кезіндегі тасымал$sl$, true),
    ($sl$2.3$sl$, $sl$AND: «және»$sl$, $sl$lec/ch2-sw-and.svg$sl$, $sl$Тізбектей қосылған екі ажыратқыш: шам екеуі де жабық болғанда жанады$sl$, false),
    ($sl$2.3$sl$, $sl$OR: «немесе»$sl$, $sl$lec/ch2-sw-or.svg$sl$, $sl$Параллель қосылған екі ажыратқыш: біреуі жабық болса шам жанады$sl$, false),
    ($sl$2.3$sl$, $sl$NOT: «емес»$sl$, $sl$lec/ch2-sw-not.svg$sl$, $sl$Шамға параллель ажыратқыш: жабық болса шам өшеді, ашық болса жанады$sl$, false),
    ($sl$2.4$sl$, $sl$Кестеде неше жол болады?$sl$, $sl$lec/ch2-rows.svg$sl$, $sl$Жол саны 1, 2, 3, 4 айнымалыда 2, 4, 8, 16$sl$, true),
    ($sl$2.5$sl$, $sl$NOT: инвертор$sl$, $sl$lec/ch2-g-not.svg$sl$, $sl$NOT вентилінің белгісі: кіріс 1, шығыс 0$sl$, false),
    ($sl$2.5$sl$, $sl$AND: екеуі де 1$sl$, $sl$lec/ch2-g-and.svg$sl$, $sl$AND вентилінің белгісі: кірістер 1 және 1, шығыс 1$sl$, false),
    ($sl$2.5$sl$, $sl$OR: біреуі 1 жеткілікті$sl$, $sl$lec/ch2-g-or.svg$sl$, $sl$OR вентилінің белгісі: кірістер 0 және 1, шығыс 1$sl$, false),
    ($sl$2.5$sl$, $sl$XOR: кірістер әртүрлі$sl$, $sl$lec/ch2-g-xor.svg$sl$, $sl$XOR вентилінің белгісі: кірістер 1 және 1, шығыс 0$sl$, false),
    ($sl$2.5$sl$, $sl$Схеманы оқу: шам қашан жанады?$sl$, $sl$lec/ch2-circuit.svg$sl$, $sl$(S1 AND S2) OR S3 схемасы: AND, содан кейін OR, шығыста шам$sl$, true)
  ) as t(pref, stitle, img, alt, dropcode)
  loop
    update public.cf_lessons l set updated_at = now(), slides = (
      select jsonb_agg(case when s->>'title' = r.stitle then (case when r.dropcode then s - 'code' - 'lang' else s end) || jsonb_build_object('img', r.img, 'alt', r.alt) else s end order by o)
      from jsonb_array_elements(l.slides) with ordinality a(s, o))
    where l.id in (select lesson_id from public.cf_curr_lessons where module_id = m) and l.title like r.pref || ' %';
    get diagnostics n = row_count;
    if n <> 1 then raise exception 'lesson % updated % rows', r.pref, n; end if;
  end loop;
end;
$ch2img$;
